-- Preserve payroll classifications used by the dictionary, UI and rate lookup.
-- Only append ENUM labels: existing values, ordinals, rates and rows stay intact.
-- No production data update; normal migration deployment performs this schema repair.
SET @aw_payroll_category_type = (SELECT COLUMN_TYPE FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='payroll_service_code_rules' AND COLUMN_NAME='category');
SET @aw_payroll_category_data_type = (SELECT DATA_TYPE FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='payroll_service_code_rules' AND COLUMN_NAME='category');
SET @aw_payroll_category_nullable = (SELECT IS_NULLABLE FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='payroll_service_code_rules' AND COLUMN_NAME='category');
SET @aw_payroll_category_default = (SELECT COLUMN_DEFAULT FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='payroll_service_code_rules' AND COLUMN_NAME='category');
SET @aw_payroll_category_comment = (SELECT COLUMN_COMMENT FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='payroll_service_code_rules' AND COLUMN_NAME='category');
SET @aw_payroll_category_charset = (SELECT CHARACTER_SET_NAME FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='payroll_service_code_rules' AND COLUMN_NAME='category');
SET @aw_payroll_category_collation = (SELECT COLLATION_NAME FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='payroll_service_code_rules' AND COLUMN_NAME='category');
SET @aw_payroll_category_length = (SELECT CHARACTER_MAXIMUM_LENGTH FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='payroll_service_code_rules' AND COLUMN_NAME='category');
SET @aw_payroll_category_next = @aw_payroll_category_type;
SET @aw_payroll_category_next = IF(@aw_payroll_category_data_type='enum' AND NOT REGEXP_LIKE(@aw_payroll_category_next,CONCAT('(^enum',CHAR(92),'(|,)',QUOTE('admin'),'(,|',CHAR(92),')$)'),IF(@aw_payroll_category_collation REGEXP '(_bin|_cs)$','c','i')),CONCAT(LEFT(@aw_payroll_category_next,LENGTH(@aw_payroll_category_next)-1),',',QUOTE('admin'),')'),@aw_payroll_category_next);
SET @aw_payroll_category_next = IF(@aw_payroll_category_data_type='enum' AND NOT REGEXP_LIKE(@aw_payroll_category_next,CONCAT('(^enum',CHAR(92),'(|,)',QUOTE('meeting'),'(,|',CHAR(92),')$)'),IF(@aw_payroll_category_collation REGEXP '(_bin|_cs)$','c','i')),CONCAT(LEFT(@aw_payroll_category_next,LENGTH(@aw_payroll_category_next)-1),',',QUOTE('meeting'),')'),@aw_payroll_category_next);
SET @aw_payroll_category_next = IF(@aw_payroll_category_data_type='enum' AND NOT REGEXP_LIKE(@aw_payroll_category_next,CONCAT('(^enum',CHAR(92),'(|,)',QUOTE('mileage'),'(,|',CHAR(92),')$)'),IF(@aw_payroll_category_collation REGEXP '(_bin|_cs)$','c','i')),CONCAT(LEFT(@aw_payroll_category_next,LENGTH(@aw_payroll_category_next)-1),',',QUOTE('mileage'),')'),@aw_payroll_category_next);
SET @aw_payroll_category_next = IF(@aw_payroll_category_data_type='enum' AND NOT REGEXP_LIKE(@aw_payroll_category_next,CONCAT('(^enum',CHAR(92),'(|,)',QUOTE('bonus'),'(,|',CHAR(92),')$)'),IF(@aw_payroll_category_collation REGEXP '(_bin|_cs)$','c','i')),CONCAT(LEFT(@aw_payroll_category_next,LENGTH(@aw_payroll_category_next)-1),',',QUOTE('bonus'),')'),@aw_payroll_category_next);
SET @aw_payroll_category_next = IF(@aw_payroll_category_data_type='enum' AND NOT REGEXP_LIKE(@aw_payroll_category_next,CONCAT('(^enum',CHAR(92),'(|,)',QUOTE('reimbursement'),'(,|',CHAR(92),')$)'),IF(@aw_payroll_category_collation REGEXP '(_bin|_cs)$','c','i')),CONCAT(LEFT(@aw_payroll_category_next,LENGTH(@aw_payroll_category_next)-1),',',QUOTE('reimbursement'),')'),@aw_payroll_category_next);
SET @aw_payroll_category_next = IF(@aw_payroll_category_data_type='enum' AND NOT REGEXP_LIKE(@aw_payroll_category_next,CONCAT('(^enum',CHAR(92),'(|,)',QUOTE('other_pay'),'(,|',CHAR(92),')$)'),IF(@aw_payroll_category_collation REGEXP '(_bin|_cs)$','c','i')),CONCAT(LEFT(@aw_payroll_category_next,LENGTH(@aw_payroll_category_next)-1),',',QUOTE('other_pay'),')'),@aw_payroll_category_next);
SET @aw_payroll_category_next = IF(@aw_payroll_category_data_type='enum' AND NOT REGEXP_LIKE(@aw_payroll_category_next,CONCAT('(^enum',CHAR(92),'(|,)',QUOTE('tutoring'),'(,|',CHAR(92),')$)'),IF(@aw_payroll_category_collation REGEXP '(_bin|_cs)$','c','i')),CONCAT(LEFT(@aw_payroll_category_next,LENGTH(@aw_payroll_category_next)-1),',',QUOTE('tutoring'),')'),@aw_payroll_category_next);
SET @aw_payroll_category_next = IF(@aw_payroll_category_data_type='enum' AND NOT REGEXP_LIKE(@aw_payroll_category_next,CONCAT('(^enum',CHAR(92),'(|,)',QUOTE('homework_help'),'(,|',CHAR(92),')$)'),IF(@aw_payroll_category_collation REGEXP '(_bin|_cs)$','c','i')),CONCAT(LEFT(@aw_payroll_category_next,LENGTH(@aw_payroll_category_next)-1),',',QUOTE('homework_help'),')'),@aw_payroll_category_next);
-- Existing VARCHAR/TEXT projections already accepting these labels need no ENUM conversion.
SET @aw_payroll_category_next = IF(@aw_payroll_category_data_type='varchar' AND @aw_payroll_category_length<13,'varchar(13)',@aw_payroll_category_next);
SET @aw_payroll_category_sql = IF(@aw_payroll_category_next IS NULL OR @aw_payroll_category_next=@aw_payroll_category_type,'SELECT 1',CONCAT('ALTER TABLE payroll_service_code_rules MODIFY COLUMN category ',@aw_payroll_category_next,' CHARACTER SET ',@aw_payroll_category_charset,' COLLATE ',@aw_payroll_category_collation,' ',IF(@aw_payroll_category_nullable='YES','NULL','NOT NULL'),IF(@aw_payroll_category_default IS NOT NULL,CONCAT(' DEFAULT ',QUOTE(@aw_payroll_category_default)),IF(@aw_payroll_category_nullable='YES',' DEFAULT NULL','')), ' COMMENT ',QUOTE(COALESCE(@aw_payroll_category_comment,'')),', ALGORITHM=INPLACE, LOCK=NONE'));
PREPARE aw_payroll_category_statement FROM @aw_payroll_category_sql;
EXECUTE aw_payroll_category_statement;
DEALLOCATE PREPARE aw_payroll_category_statement;
